update user_current_read
set chapter_id = #{chapterId},
    sort_id = #{sortId}
where chapter_id = #{deletedChapterId}

update user_current_read
set chapter_id = #{chapterId},
    sort_id = #{sortId},
    last_read_time = now()
where state = 0
  and user_id = #{userId}
  and book_id = #{bookId}
  and sort_id < #{sortId}
